"""Sun, moon and clouds for the level skies (day, small, storm and night clouds).
img(name) gives the surface; scaled(name, w, h) a cached resized copy."""
import base64
import io
import pygame

PNG = {
  'cloud_day_0': ('png', ''),
  'cloud_day_1': ('png', ''),
  'cloud_day_10': ('png', ''),
  'cloud_day_2': ('png', ''),
  'cloud_day_3': ('png', ''),
  'cloud_day_4': ('png', ''),
  'cloud_day_5': ('png', ''),
  'cloud_day_6': ('png', ''),
  'cloud_day_7': ('png', ''),
  'cloud_day_8': ('png', ''),
  'cloud_day_9': ('png', ''),
  'cloud_night_0': ('png', ''),
  'cloud_night_1': ('png', ''),
  'cloud_night_2': ('png', ''),
  'cloud_small_0': ('png', ''),
  'cloud_small_1': ('png', ''),
  'cloud_small_2': ('png', ''),
  'cloud_small_3': ('png', ''),
  'cloud_small_4': ('png', ''),
  'cloud_storm_0': ('png', ''),
  'cloud_storm_1': ('png', ''),
  'cloud_storm_2': ('png', ''),
  'cloud_storm_3': ('png', ''),
  'sky_moon': ('png', ''),
  'sky_sun': ('png', ''),
}
_C = {}


def has(name):
  return name in PNG


def img(name):
  s = _C.get(name)
  if s is None:
    ext, data = PNG[name]
    s = pygame.image.load(io.BytesIO(base64.b64decode(data)), 'art.' + ext)
    try:
      s = s.convert_alpha()
    except Exception:
      pass
    _C[name] = s
  return s


def scaled(name, w, h, smooth=True):
  k = (name, int(w), int(h))
  s = _C.get(k)
  if s is None:
    src = img(name)
    fn = getattr(pygame.transform, 'smoothscale', None) if smooth else None
    try:
      s = (fn or pygame.transform.scale)(src, (max(1, int(w)), max(1, int(h))))
    except Exception:
      s = pygame.transform.scale(src, (max(1, int(w)), max(1, int(h))))
    _C[k] = s
  return s
